import { ScheduleStore } from '../persistence/scheduleReports/scheduleStore';
import { buildWhitelistOverviewModal } from '../modals/whiteListModal';
import { ConfigActionId } from '../definition/config';
import { buildLanguageSelectModal } from '../modals/setLanguage';
import { LanguagePreferenceStorage } from '../persistence/languagePreferenceStorage';
import { getTranslations } from '../lib/translations';
import { Translations } from '../definition/languagepreference';

export class BlockActionHandler {
	constructor(
		private readonly read: IRead,
		private readonly http: IHttp,
		private readonly persistence: IPersistence,
		private readonly modify: IModify,
		private readonly context: UIKitBlockInteractionContext,
		private readonly appId: string,
	) {}
	private cachedTranslations: Translations | undefined;
	private async getT(): Promise<Translations> {
		if (this.cachedTranslations) return this.cachedTranslations;
		const { user } = this.context.getInteractionData();
		const langStore = new LanguagePreferenceStorage(
			this.persistence,
			this.read.getPersistenceReader(),
			user.id,
		);
		const lang = await langStore.getLanguage();
		this.cachedTranslations = getTranslations(lang);
		return this.cachedTranslations;
	}
	public async handle(): Promise<IUIKitResponse> {
		const { actionId, value, user, triggerId } =
			this.context.getInteractionData();
		const t = await this.getT();
		const roomStorage = new RoomInteractionStorage(
			this.persistence,
			this.read.getPersistenceReader(),
			user.id,
		);
		if (actionId.startsWith(EditLevelActionId.RESET_TO_DEFAULT)) {
			if (!triggerId) {
				return this.context.getInteractionResponder().errorResponse();
			}

			const raw = parseInt(value ?? '', 10);
			const level: SpammingLevel = CONFIGURABLE_LEVELS.includes(
				raw as SpammingLevel,
			)
				? (raw as SpammingLevel)
				: CONFIGURABLE_LEVELS[0];

			const roomId = await roomStorage.getInteractionRoomId();

			const confirmModal = buildResetLevelConfirmModal(
				level,
				levelLabel(level),
				this.appId,
				t,
				roomId ?? undefined,
			);

			await this.modify
				.getUiController()
				.openSurfaceView(confirmModal, { triggerId }, user);

			return this.context.getInteractionResponder().successResponse();
		}
		if (actionId === EditLevelActionId.BACK_TO_OVERVIEW) {
			if (!triggerId) {
				return this.context.getInteractionResponder().errorResponse();
			}

			const overviewModal = await buildLevelConfigOverviewModal(
				this.read,
				this.appId,
				t,
			);

			await this.modify
				.getUiController()
				.openSurfaceView(overviewModal, { triggerId }, user);

			return this.context.getInteractionResponder().successResponse();
		}
		if (actionId.startsWith(ConfigActionId.OPEN_ITEM_PREFIX)) {
			if (!triggerId) {
				return this.context.getInteractionResponder().errorResponse();
			}

			const entryId =
				value ?? actionId.slice(ConfigActionId.OPEN_ITEM_PREFIX.length);

			switch (entryId) {
				case 'whitelist': {
					const modal = await buildWhitelistOverviewModal(
						this.read,
						this.appId,
						t,
					);
					await this.modify
						.getUiController()
						.openSurfaceView(modal, { triggerId }, user);
					break;
				}
				case 'language': {
					const modal = await buildLanguageSelectModal(
						this.read.getPersistenceReader(),
						this.persistence,
						this.appId,
						user.id,
						t,
					);
					await this.modify
						.getUiController()
						.openSurfaceView(modal, { triggerId }, user);
					break;
				}
				default:
					break;
			}
			return this.context.getInteractionResponder().successResponse();
		}
		if (actionId.startsWith(OverviewActionId.EDIT_LEVEL_PREFIX)) {
			if (!triggerId) {
				return this.context.getInteractionResponder().errorResponse();
			}

			const raw = parseInt(value ?? '', 10);
			const level: SpammingLevel = CONFIGURABLE_LEVELS.includes(
				raw as SpammingLevel,
			)
				? (raw as SpammingLevel)
				: CONFIGURABLE_LEVELS[0];

			const editModal = await buildEditLevelModal(
				this.read,
				this.appId,
				level,
				t,
			);

			await this.modify
				.getUiController()
				.openSurfaceView(editModal, { triggerId }, user);

			return this.context.getInteractionResponder().successResponse();
		}
		if (actionId === ScheduleActionId.BACK) {
			await ScheduleDraftStorage.clear(this.persistence, user.id);
			const existing = await ScheduleStore.get(this.read);
			const setupModal = buildScheduleSetupModal(this.appId, t, existing);

			return this.context
				.getInteractionResponder()
				.updateModalViewResponse(setupModal);
		}
		if (actionId === ScheduleActionId.DELETE) {
			const existing = await ScheduleStore.get(this.read);
			if (!existing) {
				return this.context.getInteractionResponder().successResponse();
			}

			await ScheduleDraftStorage.save(this.persistence, user.id, {
				stage: 'delete',
			});
			const deleteModal = buildScheduleSetupModal(
				this.appId,
				t,
				existing,
				null,
				'delete',
			);

			return this.context
				.getInteractionResponder()
				.updateModalViewResponse(deleteModal);
		}
		if (actionId === ManageUserActionId.OPEN_MANAGE_MODAL) {
			if (!value || !triggerId) {
				return this.context.getInteractionResponder().successResponse();
			}
			// value format: "<intent>::<userId>"
			const [intent, userId] = value.split('::');

			if (intent === ManageUserActionId.OPEN_MANAGE_MODAL) {
				const targetUser = await this.read
					.getUserReader()
					.getById(userId);
				if (!targetUser) {
					return this.context
						.getInteractionResponder()
						.successResponse();
				}

				const record = await UserStatusStore.get(this.read, userId);
				if (!record) {
					return this.context
						.getInteractionResponder()
						.successResponse();
				}

				const modal = buildManageUserModal(record, this.appId, t);
				await this.modify
					.getUiController()
					.openSurfaceView(modal, { triggerId }, user);

				return this.context.getInteractionResponder().successResponse();
			}

			return this.context.getInteractionResponder().successResponse();
		}

		if (!ACTIONS_REQUIRING_CONFIRM.has(actionId)) {
			return this.context.getInteractionResponder().successResponse();
		}

		if (!value || !triggerId) {
			return this.context.getInteractionResponder().successResponse();
		}

		const roomId = await roomStorage.getInteractionRoomId();
		if (!roomId) {
			return this.context.getInteractionResponder().successResponse();
		}

		const targetUser = await this.read.getUserReader().getById(value);
		if (!targetUser) {
			return this.context.getInteractionResponder().successResponse();
		}

		const realAction = CONFIRM_TO_ACTION[actionId];
		const modal = buildConfirmActionModal(
			realAction,
			targetUser.id,
			targetUser.username,
			this.appId,
			t,
			roomId,
		);
		await this.modify
			.getUiController()
			.openSurfaceView(modal, { triggerId }, user);

		return this.context.getInteractionResponder().successResponse();
	}
}

import {
	IPersistence,
	IRead,
} from '@rocket.chat/apps-engine/definition/accessors';
import {
	RocketChatAssociationModel,
	RocketChatAssociationRecord,
} from '@rocket.chat/apps-engine/definition/metadata';
import { AdminActionLogEntry } from '../../definition/scheduleReports';
import { daysBetween } from '../../lib/utils/scheduleSummaryUtils';
import {
	MAX_RECENT_ACTIONS,
	MAX_DAILY_ACTIONS,
	DAY_RECORD_RETENTION_DAYS,
	MAX_REPORT_WINDOW_DAYS,
} from '../../constants/scheduleLogStore';
import { serialize } from '../../core/cache/keyedQueue';
import { ADMIN_ACTION_DAY_INDEX_LOCK_KEY } from '../../constants/serialiseCacheLockKeys';

export class AdminActionLogStore {
	private static dayKey(timestamp: number): string {
		return new Date(timestamp).toISOString().slice(0, 10);
	}
	private static lastPrunedDay: string | null = null;
	private static recentActionsAssocs(
		userId: string,
	): RocketChatAssociationRecord[] {
		return [
			new RocketChatAssociationRecord(
				RocketChatAssociationModel.USER,
				userId,
			),
			new RocketChatAssociationRecord(
				RocketChatAssociationModel.MISC,
				'antispam-recent-actions',
			),
		];
	}

	private static dailyActionScopeAssoc(
		day: string,
	): RocketChatAssociationRecord {
		return new RocketChatAssociationRecord(
			RocketChatAssociationModel.MISC,
			`antispam-action-day:${day}`,
		);
	}

	private static dailyActionAssocs(
		userId: string,
		day: string,
	): RocketChatAssociationRecord[] {
		return [
			new RocketChatAssociationRecord(
				RocketChatAssociationModel.USER,
				userId,
			),
			new RocketChatAssociationRecord(
				RocketChatAssociationModel.MISC,
				`antispam-action-day:${day}`,
			),
		];
	}
	private static dayIndexAssoc(): RocketChatAssociationRecord {
		return new RocketChatAssociationRecord(
			RocketChatAssociationModel.MISC,
			'antispam-action-days-index',
		);
	}
	public static async log(
		persistence: IPersistence,
		read: IRead,
		entry: AdminActionLogEntry,
	): Promise<void> {
		await serialize(entry.userId, async () => {
			const day = AdminActionLogStore.dayKey(entry.timestamp);

			const dailyAssocs = AdminActionLogStore.dailyActionAssocs(
				entry.userId,
				day,
			);
			const existingDaily = await read
				.getPersistenceReader()
				.readByAssociations(dailyAssocs);
			const dailyDoc = existingDaily.length
				? (existingDaily[0] as {
						entries: AdminActionLogEntry[];
						truncated?: boolean;
					})
				: { entries: [], truncated: false };

			if (dailyDoc.entries.length < MAX_DAILY_ACTIONS) {
				dailyDoc.entries.push(entry);
			} else {
				dailyDoc.truncated = true;
			}

			await persistence.updateByAssociations(dailyAssocs, dailyDoc, true);
			await AdminActionLogStore.pruneOldDays(persistence, read, day);

			const recentAssocs = AdminActionLogStore.recentActionsAssocs(
				entry.userId,
			);
			const existingRecent = await read
				.getPersistenceReader()
				.readByAssociations(recentAssocs);
			const recentDoc = existingRecent.length
				? (existingRecent[0] as { entries: AdminActionLogEntry[] })
				: { entries: [] };
			recentDoc.entries.push(entry);
			while (recentDoc.entries.length > MAX_RECENT_ACTIONS) {
				recentDoc.entries.shift();
			}
			await persistence.updateByAssociations(
				recentAssocs,
				recentDoc,
				true,
			);
		});
	}

	public static async getByUser(
		read: IRead,
		userId: string,
	): Promise<AdminActionLogEntry[]> {
		const records = await read
			.getPersistenceReader()
			.readByAssociations(
				AdminActionLogStore.recentActionsAssocs(userId),
			);
		if (!records.length) return [];
		const doc = records[0] as { entries: AdminActionLogEntry[] };
		return (doc.entries || []).filter((r) => r.action !== undefined);
	}

	public static async getActionsForDay(
		read: IRead,
		date: string,
	): Promise<AdminActionLogEntry[]> {
		const records = await read
			.getPersistenceReader()
			.readByAssociation(AdminActionLogStore.dailyActionScopeAssoc(date));
		const all: AdminActionLogEntry[] = [];
		for (const doc of records) {
			const typed = doc as { entries: AdminActionLogEntry[] };
			if (typed.entries)
				all.push(
					...typed.entries.filter((r) => r.action !== undefined),
				);
		}
		return all;
	}

	public static async getActionsSince(
		read: IRead,
		sinceTimestamp: number,
	): Promise<AdminActionLogEntry[]> {
		if (!Number.isFinite(sinceTimestamp)) {
			throw new Error(
				`getActionsSince: invalid sinceTimestamp: ${sinceTimestamp}`,
			);
		}

		const days = daysBetween(sinceTimestamp).slice(-MAX_REPORT_WINDOW_DAYS);

		const perDay = await Promise.all(
			days.map((day) => AdminActionLogStore.getActionsForDay(read, day)),
		);
		return perDay
			.reduce((acc, day) => acc.concat(day), [])
			.filter((entry) => entry.timestamp >= sinceTimestamp);
	}
	private static async pruneOldDays(
		persistence: IPersistence,
		read: IRead,
		day: string,
	): Promise<void> {
		await serialize(ADMIN_ACTION_DAY_INDEX_LOCK_KEY, async () => {
			if (day === AdminActionLogStore.lastPrunedDay) return;
			const indexAssoc = AdminActionLogStore.dayIndexAssoc();
			const existingIndex = await read
				.getPersistenceReader()
				.readByAssociation(indexAssoc);
			const indexDoc = existingIndex.length
				? (existingIndex[0] as { days: string[] })
				: { days: [] };

			if (!indexDoc.days.includes(day)) {
				indexDoc.days.push(day);
			}

			const cutoff = new Date();
			cutoff.setUTCDate(cutoff.getUTCDate() - DAY_RECORD_RETENTION_DAYS);
			const cutoffKey = cutoff.toISOString().slice(0, 10);

			const staleDays = indexDoc.days.filter((d) => d < cutoffKey);
			if (staleDays.length) {
				await Promise.all(
					staleDays.map((staleDay) =>
						persistence.removeByAssociation(
							AdminActionLogStore.dailyActionScopeAssoc(staleDay),
						),
					),
				);
				indexDoc.days = indexDoc.days.filter((d) => d >= cutoffKey);
			}

			await persistence.updateByAssociations(
				[indexAssoc],
				indexDoc,
				true,
			);
			AdminActionLogStore.lastPrunedDay = day;
		});
	}
}

import {
	IAppAccessors,
	IAppInstallationContext,
	IAppUninstallationContext,
	IConfigurationExtend,
	IConfigurationModify,
	IEnvironmentRead,
	IHttp,
	ILogger,
	IModify,
	IPersistence,
	IRead,
} from '@rocket.chat/apps-engine/definition/accessors';
import { App } from '@rocket.chat/apps-engine/definition/App';
import {
	IMessage,
	IPostMessageSent,
	IPreMessageSentPrevent,
} from '@rocket.chat/apps-engine/definition/messages';
import { IAppInfo } from '@rocket.chat/apps-engine/definition/metadata';
import { ISetting } from '@rocket.chat/apps-engine/definition/settings';
import {
	IUIKitResponse,
	UIKitBlockInteractionContext,
	UIKitViewSubmitInteractionContext,
} from '@rocket.chat/apps-engine/definition/uikit';
import { IUIKitInteractionHandler } from '@rocket.chat/apps-engine/definition/uikit/IUIKitActionHandler';
import { SpamProcessor } from './src/core/spamProcessor';
import { MessageCache } from './src/core/cache/messageCache';
import { SpamMonitorCommand } from './src/commands/commandUtilities';
import { APP_SETTINGS } from './src/config/settings';
import { AppSetting } from './src/enums/settings';
import { SpamConfig } from './src/definition/spamProcessor';
import { RestrictionManager } from './src/core/restrictionsManager';
import { UserStatusStore } from './src/persistence/userStatusStore';
import { RoomType } from '@rocket.chat/apps-engine/definition/rooms';
import { AdminChannelMessages } from './src/lib/translations/locals/en';
import {
	ADMIN_CHANNEL_DISPLAY_NAME,
	ADMIN_CHANNEL_NAME,
	MS_PER_DAY,
	MS_PER_SECOND,
} from './src/constants/config';
import { ViewSubmitHandler } from './src/handlers/viewSubmitHandler';
import { BlockActionHandler } from './src/handlers/blockActionHandler';
import { LevelConfigStore } from './src/persistence/levelConfigStore';
import {
	DAILY_REPORT_JOB_ID,
	ScheduledReporter,
} from './src/core/schedulereport';
import { IJobContext } from '@rocket.chat/apps-engine/definition/scheduler';
import { ScheduleStore } from './src/persistence/scheduleReports/scheduleStore';
import { WhitelistStore } from './src/persistence/whiteListStore';

export class AppsSpamMonitorApp
	extends App
	implements
		IPreMessageSentPrevent,
		IPostMessageSent,
		IUIKitInteractionHandler
{
	private processor: SpamProcessor | null = null;
	private cache: MessageCache;

	constructor(info: IAppInfo, logger: ILogger, accessors: IAppAccessors) {
		super(info, logger, accessors);
	}

	public async initialize(
		configurationExtend: IConfigurationExtend,
		environmentRead: IEnvironmentRead,
	): Promise<void> {
		this.cache = new MessageCache();
		await super.initialize(configurationExtend, environmentRead);
	}

	protected async extendConfiguration(
		configuration: IConfigurationExtend,
	): Promise<void> {
		await Promise.all(
			APP_SETTINGS.map((setting) =>
				configuration.settings.provideSetting(setting),
			),
		);
		await configuration.slashCommands.provideSlashCommand(
			new SpamMonitorCommand(this.getID()),
		);

		await configuration.scheduler.registerProcessors([
			{
				id: DAILY_REPORT_JOB_ID,
				processor: async (
					_jobContext: IJobContext,
					read: IRead,
					modify: IModify,
					http: IHttp,
					persis: IPersistence,
				) => {
					try {
						await ScheduledReporter.sendDailyReport(
							read,
							modify,
							http,
							persis,
							ADMIN_CHANNEL_NAME,
						);
					} catch (err) {
						this.getLogger().error(
							'[SpamMonitor] Scheduled report job failed:',
							err,
						);
					}
				},
			},
		]);
	}

	public async onEnable(
		environment: IEnvironmentRead,
		configurationModify: IConfigurationModify,
	): Promise<boolean> {
		await this.loadSettings(environment);
		try {
			const read = this.getAccessors().reader;
			const existing = await ScheduleStore.get(read);
			if (existing) {
				await configurationModify.scheduler
					.cancelJob(DAILY_REPORT_JOB_ID)
					.catch(() => {});
				await configurationModify.scheduler.scheduleRecurring({
					id: DAILY_REPORT_JOB_ID,
					interval: existing.cronExpression,
					skipImmediate: true,
				});
			}
		} catch (err) {
			this.getLogger().error(
				'[SpamMonitor] Failed to re-arm schedule on enable:',
				err,
			);
		}
		return true;
	}

	public async onInstall(
		context: IAppInstallationContext,
		read: IRead,
		_http: IHttp,
		_persistence: IPersistence,
		modify: IModify,
	): Promise<void> {
		const installer = context.user;
		const appUser = await read.getUserReader().getAppUser();
		if (!appUser) {
			return;
		}

		let room = await read.getRoomReader().getByName(ADMIN_CHANNEL_NAME);
		if (!room) {
			const roomBuilder = modify
				.getCreator()
				.startRoom()
				.setDisplayName(ADMIN_CHANNEL_DISPLAY_NAME)
				.setSlugifiedName(ADMIN_CHANNEL_NAME)
				.setType(RoomType.PRIVATE_GROUP)
				.setCreator(appUser)
				.setMembersToBeAddedByUsernames([installer.username]);

			const roomId = await modify.getCreator().finish(roomBuilder);
			room = await read.getRoomReader().getById(roomId);
		}

		if (room) {
			const msgBuilder = modify
				.getCreator()
				.startMessage()
				.setRoom(room)
				.setSender(appUser)
				.setText(AdminChannelMessages.welcome());

			await modify.getCreator().finish(msgBuilder);
		}

		await RestrictionManager.dmUser(
			read,
			modify,
			installer,
			AdminChannelMessages.installDm(ADMIN_CHANNEL_NAME),
		);
	}

	public async onUninstall(
		context: IAppUninstallationContext,
		read: IRead,
		_http: IHttp,
		_persistence: IPersistence,
		modify: IModify,
	): Promise<void> {
		try {
			const room = await read
				.getRoomReader()
				.getByName(ADMIN_CHANNEL_NAME);
			if (room) {
				try {
					await modify.getDeleter().deleteRoom(room.id);
				} catch (roomErr) {
					this.getLogger().warn(
						'[SpamMonitor] onUninstall: deleteRoom error:',
						roomErr,
					);
				}
			}

			try {
				await RestrictionManager.dmUser(
					read,
					modify,
					context.user,
					AdminChannelMessages.uninstallDm(ADMIN_CHANNEL_NAME),
				);
			} catch (dmErr) {
				this.getLogger().warn(
					'[SpamMonitor] onUninstall: DM error:',
					dmErr,
				);
			}
		} catch (err) {
			this.getLogger().error(
				'[SpamMonitor] onUninstall: unexpected error:',
				err,
			);
		}
	}

	public async onSettingUpdated(
		_setting: ISetting,
		_configurationModify: IConfigurationModify,
		read: IRead,
	): Promise<void> {
		await this.loadSettings(read.getEnvironmentReader());
	}

	private async loadSettings(env: IEnvironmentRead): Promise<void> {
		const settings = env.getSettings();
		const [
			monitoringWindowDays,
			slidingWindowSeconds,
			crossChannelThreshold,
			rateShortBurst,
			rateSustained,
		] = (await Promise.all([
			settings.getValueById(AppSetting.MonitoringWindowDays),
			settings.getValueById(AppSetting.SlidingWindowSeconds),
			settings.getValueById(AppSetting.CrossChannelThreshold),
			settings.getValueById(AppSetting.RateShortBurst),
			settings.getValueById(AppSetting.RateSustained),
		])) as number[];

		const config: SpamConfig = {
			monitoringWindowMs: monitoringWindowDays * MS_PER_DAY,
			slidingWindowMs: slidingWindowSeconds * MS_PER_SECOND,
			crossChannelThreshold,
			rateShortBurst,
			rateSustained,
		};

		if (this.processor) {
			this.processor.updateConfig(config);
		} else {
			this.processor = new SpamProcessor(this.cache, config);
		}
	}

	public async checkPreMessageSentPrevent(
		message: IMessage,
	): Promise<boolean> {
		if (!message.sender || !message.room || !message.text) return false;
		return message.room.type !== RoomType.DIRECT_MESSAGE;
	}

	public async executePreMessageSentPrevent(
		message: IMessage,
		read: IRead,
		_http: IHttp,
		persistence: IPersistence,
	): Promise<boolean> {
		if (!message.sender || !message.room) return false;
		if (await WhitelistStore.isRoomWhitelisted(read, message.room.id)) {
			return false;
		}
		if (
			await WhitelistStore.isUserWhitelistedByRole(read, message.sender)
		) {
			return false;
		}
		try {
			const { restricted } = await UserStatusStore.isRestricted(
				read,
				persistence,
				message.sender.id,
			);
			return restricted;
		} catch (err) {
			this.getLogger().error('[antispam] Error in isRestricted:', err);
			return false;
		}
	}

	public async checkPostMessageSent(message: IMessage): Promise<boolean> {
		if (!message.text || message.room.type === RoomType.DIRECT_MESSAGE)
			return false;
		return true;
	}

	public async executePostMessageSent(
		message: IMessage,
		read: IRead,
		_http: IHttp,
		persistence: IPersistence,
		modify: IModify,
	): Promise<void> {
		if (!message.sender || !message.room) return;
		const sender = await read.getUserReader().getById(message.sender.id);
		const appUser = await read.getUserReader().getAppUser();
		if (
			!sender ||
			sender.id === appUser?.id ||
			!this.processor?.isNewUser(sender)
		)
			return;
		try {
			if (await WhitelistStore.isRoomWhitelisted(read, message.room.id)) {
				return;
			}
			if (await WhitelistStore.isUserWhitelistedByRole(read, sender)) {
				return;
			}
			const result = await this.processor.analyzeMessage(
				message,
				read,
				persistence,
			);
			if (result?.flagged && result.record && result.levelChanged) {
				const levelConfig = await LevelConfigStore.get(
					read,
					result.record.spammingLevel,
				);
				await RestrictionManager.applyAction(
					read,
					modify,
					persistence,
					sender,
					result.record,
					{
						levelChanged: result.levelChanged,
						trigger: result.trigger,
						roomName: message.room.slugifiedName ?? message.room.id,
					},
					levelConfig,
				);
			}
		} catch (err) {
			this.getLogger().error('[antispam] Error in analyzeMessage:', err);
		}
	}

	public async executeBlockActionHandler(
		context: UIKitBlockInteractionContext,
		read: IRead,
		http: IHttp,
		persistence: IPersistence,
		modify: IModify,
	): Promise<IUIKitResponse> {
